type BetaRuleMatch struct {
	// Audience Exact match against the `aud` claim (any element if array). When omitted, the JWT's `aud` must still equal Anthropic's expected audience for the issuer; setting this field overrides that default.
	Audience *NullableValue[string] `json:"audience,omitempty"`
	// Claims Exact-match `{claim: value}` pairs against top-level claims. Only string-valued claims can be matched; use `condition` for non-string claims.
	Claims *NullableValue[map[string]string] `json:"claims,omitempty"`
	// Condition CEL expression over claims for logic the structural fields can't express. Must evaluate to a boolean and may reference only the `claims` variable; a constant-true expression (such as `true`) is rejected with 400.
	Condition *NullableValue[string] `json:"condition,omitempty"`
	// SubjectPrefix Match the verified JWT `sub` claim. Exact match unless the value ends with `*`, in which case it is a prefix match. Example: `repo:my-org/my-repo:ref:refs/heads/main`.
	SubjectPrefix *NullableValue[string] `json:"subject_prefix,omitempty"`
}
